580	func createAndAwaitMirror(ctx context.Context, c *coreapi.Client, owner, repo, clusterHost string, opts mirrorCreateOptions) (mirrorCreateOutcome, error) {
581		var currentPhase mirrorCreatePhase
582		reportPhase := func(phase mirrorCreatePhase) {
583			if opts.onPhase == nil || phase == currentPhase {
584				return
585			}
586			currentPhase = phase
587			opts.onPhase(phase)
588		}
589	
590		waitCtx := ctx
591		if opts.async && opts.timeout > 0 {
592			var cancel context.CancelFunc
593			waitCtx, cancel = context.WithTimeout(ctx, opts.timeout)
594			defer cancel()
595		}
596	
597		var created *coreapi.CreatedMirror
598		var err error
599		if opts.async {
600			reportPhase(mirrorCreatePhaseQueued)
601			accepted, submitErr := c.CreateMirrorRequest(waitCtx, &coreapi.CreateMirrorRequestInputBody{
602				Provider:    coreapi.CreateMirrorRequestInputBodyProviderGithub,
603				Owner:       owner,
604				Repo:        repo,
605				ClusterHost: clusterHost,
606			})
607			if submitErr != nil {
608				if waitErr := waitCtx.Err(); waitErr != nil {
609					if errors.Is(waitErr, context.Canceled) {
610						return mirrorCreateOutcome{}, NewSilentError(waitErr)
611					}
612					return mirrorCreateOutcome{}, fmt.Errorf("timed out submitting mirror request: %w", waitErr)
613				}
614				return mirrorCreateOutcome{}, submitErr
615			}
616			location, _ := accepted.Location.Get()
617			created, err = awaitMirrorPlacement(waitCtx, c, accepted.Response, location, func(status coreapi.MirrorRequestStatus) {
618				switch status {
619				case coreapi.MirrorRequestStatusPending:
620					reportPhase(mirrorCreatePhaseQueued)
621				case coreapi.MirrorRequestStatusProcessing:
622					reportPhase(mirrorCreatePhasePlacing)
623				case coreapi.MirrorRequestStatusSucceeded, coreapi.MirrorRequestStatusFailed:
624				}
625			})
626		} else {
627			reportPhase(mirrorCreatePhasePlacing)
628			created, err = c.CreateMirror(ctx, &coreapi.CreateMirrorInputBody{
629				Provider:    coreapi.CreateMirrorInputBodyProviderGithub,
630				Owner:       owner,
631				Repo:        repo,
632				ClusterHost: clusterHost,
633			})
634		}
635		if err != nil {
636			return mirrorCreateOutcome{}, err
637		}
638		outcome := mirrorCreateOutcome{created: created, createdStateUnknown: opts.async}
639		if created.Suspended {
640			// The placement already existed and an admin has suspended it, so it
641			// will never serve — skip the clone poll. The caller warns after echoing
642			// the placement; a suspended re-create is still a (non-fatal) success,
643			// so return no error.
644			return outcome, nil
645		}
646		if created.Empty { //nolint:staticcheck // CreatedMirror.Empty deprecated by /repos spec bump; create-flow cleanup tracked separately
647			// An empty upstream has nothing to clone, so don't poll for "ready" — it
648			// never would. But an *existing* placement can be suspended even when
649			// empty, and one status read surfaces that (a fresh create can't be
650			// suspended — suspension follows upstream access loss). Mirrors the old
651			// finishMirrorCreate behavior; the read is best-effort, so a transient
652			// GetMirror error just falls through to the benign "nothing to clone".
653			if !created.Created {
654				if m, gerr := c.GetMirror(ctx, coreapi.GetMirrorParams{MirrorId: created.MirrorId}); gerr == nil {
655					if s, ok := m.Status.Get(); ok && s == coreapi.MirrorStatusSuspended {
656						outcome.status = s
657						outcome.polled = true
658						return outcome, errMirrorSuspended
659					}
660				}
661			}
662			return outcome, nil
663		}
664		if opts.noWait {
665			return outcome, nil
666		}
667		reportPhase(mirrorCreatePhaseCloning)
668		pollTimeout := opts.timeout
669		if opts.async {
670			pollTimeout = 0
671		}
672		status, werr := awaitMirrorReady(waitCtx, c, created.MirrorId, pollTimeout)
673		outcome.status = status
674		outcome.polled = true
675		return outcome, werr
676	}
