17	// gitHubHTTPSRe / gitHubSSHRe / gitHubBareRe parse the GitHub URL shapes
18	// `mirror create`/`remove` accept, mirroring the standalone entiredb CLI:
19	//
20	//	https://github.com/<owner>/<repo>(.git)
21	//	git@github.com:<owner>/<repo>(.git)
22	//	(github.com/)<owner>/<repo>
23	//
24	// owner/repo are lowercased so the synthesised /gh/<owner>/<repo> slug
25	// matches what the server persists.
26	//
27	// The owner/repo capture groups are restricted to GitHub's real identifier
28	// charset rather than a permissive "anything but slash". owner/repo flow
29	// unescaped into the STS audience (entireclient/repocreds) and the clone URL;
30	// a loose pattern would admit ?, #, %, .. and control chars, letting a name
31	// like `repo?bypass=1` smuggle a query string or `repo#x` truncate the path.
32	// GitHub owners are [A-Za-z0-9-] and repos are [A-Za-z0-9._-], so matching
33	// upstream reality closes those vectors at the boundary instead of relying on
34	// whatever the server does with weird strings.
35	const (
36		gitHubOwnerPat = `([A-Za-z0-9-]+)`
37		gitHubRepoPat  = `([A-Za-z0-9._-]+?)`
38	)
39	
40	var (
41		gitHubHTTPSRe = regexp.MustCompile(`^https?://github\.com/` + gitHubOwnerPat + `/` + gitHubRepoPat + `(?:\.git)?$`)
42		gitHubSSHRe   = regexp.MustCompile(`^git@github\.com:` + gitHubOwnerPat + `/` + gitHubRepoPat + `(?:\.git)?$`)
43		gitHubBareRe  = regexp.MustCompile(`^(?:github\.com/)?` + gitHubOwnerPat + `/` + gitHubRepoPat + `(?:\.git)?$`)
44	
45		// gitHubDotOnlyRe matches repo segments that are entirely dots
46		// (".", "..", ...). The tightened owner charset already excludes
47		// dots, but gitHubRepoPat allows ".", and a dot-only repo name would
48		// embed a literal ".." in both /gh/<owner>/<repo> and the
49		// token-exchange audience. Reject at the boundary.
50		gitHubDotOnlyRe = regexp.MustCompile(`^\.+$`)
51	)
52	
53	func parseGitHubURL(rawURL string) (owner, repo string, err error) {
54		for _, re := range []*regexp.Regexp{gitHubHTTPSRe, gitHubSSHRe, gitHubBareRe} {
55			m := re.FindStringSubmatch(rawURL)
56			if m == nil {
57				continue
58			}
59			owner, repo = strings.ToLower(m[1]), strings.ToLower(m[2])
60			if gitHubDotOnlyRe.MatchString(repo) {
61				return "", "", fmt.Errorf("invalid GitHub URL: repo cannot be dot-only: %s", rawURL)
62			}
63			return owner, repo, nil
64		}
65		return "", "", fmt.Errorf("not a recognized GitHub URL: %s", rawURL)
66	}
