95	func awaitMirrorPlacement(ctx context.Context, c mirrorRequestGetter, initial coreapi.MirrorRequest, location string, onStatus func(coreapi.MirrorRequestStatus)) (*coreapi.CreatedMirror, error) {
96		ctx, requestID, err := mirrorRequestPollTarget(ctx, location)
97		if err != nil {
98			return nil, err
99		}
100		if initial.RequestId != requestID {
101			return nil, fmt.Errorf("mirror request Location identifies %s but response identifies %s", requestID, initial.RequestId)
102		}
103	
104		ticker := time.NewTicker(mirrorPollInterval)
105		defer ticker.Stop()
106	
107		request := &initial
108		var lastStatus coreapi.MirrorRequestStatus
109		var consecutiveErrs int
110		for {
111			if request.Status != lastStatus {
112				lastStatus = request.Status
113				if onStatus != nil {
114					onStatus(request.Status)
115				}
116			}
117			switch request.Status {
118			case coreapi.MirrorRequestStatusSucceeded:
119				result, ok := request.Result.Get()
120				if !ok || result.MirrorId == "" || result.MirrorUrl == "" {
121					return nil, errors.New("mirror request succeeded without a mirror id and URL")
122				}
123				return &coreapi.CreatedMirror{
124					MirrorId:  result.MirrorId,
125					MirrorUrl: result.MirrorUrl,
126					PublicUrl: result.PublicUrl,
127				}, nil
128			case coreapi.MirrorRequestStatusFailed:
129				return nil, mirrorRequestFailureError(*request)
130			case coreapi.MirrorRequestStatusPending, coreapi.MirrorRequestStatusProcessing:
131			default:
132				return nil, fmt.Errorf("mirror request returned unknown status %q", request.Status)
133			}
134	
135			select {
136			case <-ctx.Done():
137				return nil, classifyPlacementWaitContextErr(ctx.Err())
138			case <-ticker.C:
139			}
140	
141			next, err := c.GetMirrorRequest(ctx, coreapi.GetMirrorRequestParams{RequestId: requestID})
142			if err != nil {
143				if ctx.Err() != nil {
144					return nil, classifyPlacementWaitContextErr(ctx.Err())
145				}
146				consecutiveErrs++
147				if consecutiveErrs >= maxConsecutivePollErrors {
148					return nil, fmt.Errorf("poll mirror request: %w", err)
149				}
150				continue
151			}
152			consecutiveErrs = 0
153			if next.RequestId != requestID {
154				return nil, fmt.Errorf("mirror request poll returned id %s, want %s", next.RequestId, requestID)
155			}
156			request = next
157		}
158	}
