160	func mirrorRequestPollTarget(ctx context.Context, location string) (context.Context, uuid.UUID, error) {
161		if strings.TrimSpace(location) == "" {
162			return ctx, uuid.Nil, errors.New("mirror request response is missing Location")
163		}
164		locationURL, err := url.Parse(location)
165		if err != nil || locationURL.User != nil || locationURL.RawQuery != "" || locationURL.Fragment != "" {
166			return ctx, uuid.Nil, fmt.Errorf("invalid mirror request Location %q", location)
167		}
168		const prefix = "/api/v1/mirror-requests/"
169		requestIDText, ok := strings.CutPrefix(locationURL.Path, prefix)
170		if !ok || requestIDText == "" || strings.Contains(requestIDText, "/") {
171			return ctx, uuid.Nil, fmt.Errorf("invalid mirror request Location %q", location)
172		}
173		requestID, err := uuid.Parse(requestIDText)
174		if err != nil {
175			return ctx, uuid.Nil, fmt.Errorf("invalid mirror request Location %q: %w", location, err)
176		}
177		if locationURL.IsAbs() {
178			if locationURL.Scheme != "https" && locationURL.Scheme != "http" {
179				return ctx, uuid.Nil, fmt.Errorf("invalid mirror request Location %q", location)
180			}
181			serverURL := &url.URL{Scheme: locationURL.Scheme, Host: locationURL.Host, Path: "/api/v1"}
182			ctx = coreapi.WithServerURL(ctx, serverURL)
183		} else if locationURL.Host != "" || !strings.HasPrefix(locationURL.Path, "/") {
184			return ctx, uuid.Nil, fmt.Errorf("invalid mirror request Location %q", location)
185		}
186		return ctx, requestID, nil
187	}
