189	func mirrorRequestFailureError(request coreapi.MirrorRequest) error {
190		failure, ok := request.Failure.Get()
191		if !ok {
192			return errors.New("mirror placement failed without failure details")
193		}
194	
195		known := false
196		switch failure.Code {
197		case "repo_inaccessible", "github_link_required", "source_too_large", "github_unavailable",
198			"mirror_url_conflict", "mirror_conflict", "placement_deleted", "mirror_name_conflict",
199			"invalid_request", "internal":
200			known = true
201		}
202		var message string
203		if known {
204			message = fmt.Sprintf("mirror placement failed (%s): %s", failure.Code, failure.Message)
205		} else {
206			message = fmt.Sprintf("mirror placement failed with unknown failure code %q: %s", failure.Code, failure.Message)
207		}
208		if failure.Retryable {
209			message += "; retry this command"
210		}
211		return errors.New(message)
212	}
