214	// awaitMirrorReady polls the control plane for a mirror's clone lifecycle until
215	// it reaches a terminal status or the deadline/cancellation fires. It returns
216	// the last observed status plus:
217	//
218	//   - nil                     when ready (the repo is clonable)
219	//   - errMirrorCloneFailed    when the initial clone failed
220	//   - errMirrorSuspended      when the placement is suspended
221	//   - a timeout/transport err when the wait deadline passed, or polls kept
222	//     erroring past maxConsecutivePollErrors (transient glitches are retried)
223	//
224	// "processing" keeps the loop running. This replaces the old smart-HTTP
225	// info/refs probe: the control plane now reports clone readiness directly via
226	// Mirror.status, so a single authenticated control-plane call per tick suffices
227	// — no repo-scoped token exchange or data-plane round trip.
228	func awaitMirrorReady(ctx context.Context, c mirrorStatusGetter, mirrorID string, timeout time.Duration) (coreapi.MirrorStatus, error) {
229		if timeout > 0 {
230			var cancel context.CancelFunc
231			ctx, cancel = context.WithTimeout(ctx, timeout)
232			defer cancel()
233		}
234		ticker := time.NewTicker(mirrorPollInterval)
235		defer ticker.Stop()
236	
237		var last coreapi.MirrorStatus
238		var consecutiveErrs int
239		for {
240			m, err := c.GetMirror(ctx, coreapi.GetMirrorParams{MirrorId: mirrorID})
241			switch {
242			case err != nil:
243				if ctx.Err() != nil {
244					return last, classifyWaitContextErr(ctx.Err())
245				}
246				// Tolerate transient glitches: the clone may still be progressing,
247				// so retry on the next tick. Only give up once errors persist.
248				consecutiveErrs++
249				if consecutiveErrs >= maxConsecutivePollErrors {
250					return last, fmt.Errorf("poll mirror status: %w", err)
251				}
252			default:
253				consecutiveErrs = 0
254				if s, ok := m.Status.Get(); ok {
255					last = s
256					switch s {
257					case coreapi.MirrorStatusReady:
258						return s, nil
259					case coreapi.MirrorStatusFailed:
260						return s, errMirrorCloneFailed
261					case coreapi.MirrorStatusSuspended:
262						return s, errMirrorSuspended
263					case coreapi.MirrorStatusProcessing:
264						// keep waiting
265					}
266				}
267			}
268			select {
269			case <-ctx.Done():
270				return last, classifyWaitContextErr(ctx.Err())
271			case <-ticker.C:
272			}
273		}
274	}
